function drawPart(c,x,y,type,rot=0,scale=1){let color=defs[type].color;c.save();c.translate(x,y);c.rotate(rot*Math.PI/2);c.scale(scale,scale);c.fillStyle=color;c.strokeStyle='#283940';c.lineWidth=1.5;if(type==='engine'){c.fillRect(-12,-13,24,24);c.fillStyle='#364b53';c.fillRect(-8,8,16,6);c.fillStyle='#ffd38c';c.beginPath();c.moveTo(-6,14);c.lineTo(0,27);c.lineTo(6,14);c.fill()}else if(type==='fin'){c.beginPath();c.moveTo(-12,-12);c.lineTo(13,-8);c.lineTo(10,8);c.lineTo(-12,13);c.closePath();c.fill();c.stroke()}else if(type==='nose'||type==='armor'){c.beginPath();c.moveTo(-13,10);c.lineTo(0,-17);c.lineTo(13,10);c.closePath();c.fill();c.stroke();if(type==='armor'){c.strokeStyle='#fff';c.beginPath();c.moveTo(0,-11);c.lineTo(0,8);c.stroke()}}else{c.fillRect(-12,-15,24,30);c.strokeRect(-12,-15,24,30);if(type==='warhead'){c.fillStyle='#fff4c9';c.beginPath();c.arc(0,0,5,0,7);c.fill()}if(type==='separator'){c.fillStyle='#34494c';c.fillRect(-14,-3,28,6)}if(type==='explosive'){c.fillStyle='#ffe1a4';c.fillRect(-3,-8,6,16)}}c.restore()}
function drawRocket(c,list,flame=0){let s=11;c.fillStyle='#e7e8d9';c.strokeStyle='#354750';c.lineWidth=1.5;list.filter(p=>p.attached!==false).forEach(p=>{let x=p.x*s,y=(p.y-1)*s; c.save();c.translate(x,y);c.rotate(p.rot*Math.PI/2);let d=defs[p.type];c.fillStyle=d.color;if(p.type==='nose'||p.type==='armor'){c.beginPath();c.moveTo(-s*.45,-s*.55);c.lineTo(0,-s*1.6);c.lineTo(s*.45,-s*.55);c.closePath();c.fill();c.stroke()}else if(p.type==='fin'){c.beginPath();c.moveTo(-s*.5,-s*.5);c.lineTo(s*.65,-s*.4);c.lineTo(s*.5,s*.4);c.lineTo(-s*.5,s*.5);c.closePath();c.fill();c.stroke()}else{c.fillRect(-s*.43,-s*.52,s*.86,s*1.04);c.strokeRect(-s*.43,-s*.52,s*.86,s*1.04);if(p.type==='engine'){c.fillStyle='#45555a';c.fillRect(-s*.29,s*.47,s*.58,s*.3)}}c.restore()});let engines=list.filter(p=>p.type==='engine'&&p.attached!==false);if(flame>0)engines.forEach(e=>{let x=e.x*s,y=(e.y-1)*s+s*.9;let f=12+Math.random()*18;c.fillStyle='#f8b457';c.beginPath();c.moveTo(x-s*.25,y);c.lineTo(x,y+f*flame);c.lineTo(x+s*.25,y);c.closePath();c.fill();c.fillStyle='#fff0b0';c.beginPath();c.moveTo(x-s*.1,y);c.lineTo(x,y+f*.55*flame);c.lineTo(x+s*.1,y);c.fill()})}
function drawMini(){let r=map.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(map.width!==Math.round(r.width*dpr)||map.height!==Math.round(r.height*dpr)){map.width=Math.round(r.width*dpr);map.height=Math.round(r.height*dpr)}mctx.setTransform(dpr,0,0,dpr,0,0);let w=r.width,h=r.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#213541';mctx.fillRect(0,0,w,h);mctx.beginPath();for(let x=0;x<=w;x+=2){let wx=x/w*W;mctx.lineTo(x,h-(ground(wx)+25)/1500*h)}mctx.lineTo(w,h);mctx.lineTo(0,h);mctx.closePath();mctx.fillStyle='#91aa77';mctx.fill();mctx.strokeStyle='#c2dfae';mctx.lineWidth=1;mctx.stroke();mctx.fillStyle='#6eb5da';mctx.fillRect(2,h-15,7,9);structures.filter(s=>s.alive).forEach(s=>{mctx.fillStyle='#ee7260';mctx.beginPath();mctx.arc(s.x/W*w,h-(s.y+s.h)/1500*h,2.4,0,7);mctx.fill()});if(rocket&&rocket.alive){let x=rocket.x/W*w,y=h-(rocket.y/1500*h);mctx.beginPath();mctx.moveTo(x,y);mctx.lineTo(Math.min(w,x+rocket.vx*.12),y-rocket.vy*.08);mctx.strokeStyle='#57b1db';mctx.setLineDash([3,3]);mctx.stroke();mctx.setLineDash([]);mctx.fillStyle='#64c6ed';mctx.beginPath();mctx.arc(x,y,3,0,7);mctx.fill()}if(freeCam){mctx.strokeStyle='#ffffffaa';mctx.strokeRect(Math.max(0,camera.x/W*w-12),0,24,h)}}
function tick(t){let dt=Math.min(.04,(t-last)/1000||.016);last=t;if(rocket&&phase==='flight'&&rocket.alive){let engines=parts.filter(p=>p.type==='engine'&&p.attached!==false),thrust=engines.reduce((a,p)=>a+p.throttle/100*defs.engine.thrust,0);let tank=parts.filter(p=>p.type==='tank'&&p.attached!==false).length;let burning=rocket.fuel>0&&thrust>0;rocket.flame=burning?1:0;if(burning){rocket.fuel-=dt*thrust/210*1.7;rocket.vx+=Math.cos(rocket.angle)*thrust/rocket.mass*dt;rocket.vy+=Math.sin(rocket.angle)*thrust/rocket.mass*dt}rocket.vy-=125*dt;rocket.vx*=.999;rocket.x+=rocket.vx*dt;rocket.y+=rocket.vy*dt;
// control surfaces make steering more responsive; wind drag
let fins=parts.filter(p=>p.type==='fin'&&p.attached!==false).length;if(fins)rocket.angle+=(Math.sin(frame*.035)*.0015*fins);
for(let s of structures){if(!s.alive)continue;let collisionX=Math.abs(rocket.x-s.x)<s.w*.5+11,collisionY=rocket.y>s.y&&rocket.y<s.y+s.h;if(collisionX&&collisionY){explode(rocket.x,rocket.y,parts.some(p=>p.type==='warhead')?130:74,parts.some(p=>p.type==='warhead')?7:4);rocket.hp--;if(rocket.hp>0){rocket.vx*=.5;rocket.vy*=.48;rocket.y+=30;showToast('Impact! Piercing through the stronghold…')}else{rocket.alive=false;finishFlight()}break}}
if(rocket.alive&&rocket.y<=ground(rocket.x)+12){rocket.y=ground(rocket.x)+12;explode(rocket.x,rocket.y,parts.some(p=>p.type==='warhead')?115:50,parts.some(p=>p.type==='warhead')?6:2);rocket.alive=false;finishFlight()}if(rocket.x>W||rocket.y>H||rocket.x< -100){rocket.alive=false;finishFlight()}}
for(let d of debris){d.vy-=130*dt;d.x+=d.vx*dt;d.y+=d.vy*dt;d.life-=dt;if(d.y<ground(d.x)){d.y=ground(d.x);d.vy=0;d.vx*=.6}}debris=debris.filter(d=>d.life>0);explosions.forEach(e=>{e.r+=(e.max-e.r)*dt*8;e.life-=dt*1.5});explosions=explosions.filter(e=>e.life>0);requestAnimationFrame(tick)}

