 function explode(x,y,r,damage){explosions.push({x,y,r:2,max:r,life:1});for(let s of structures){if(!s.alive)continue;let dist=Math.hypot(s.x-x,(s.y+s.h/2)-y);if(dist<r+s.w*.4){let power=Math.max(.4,1-dist/(r+s.w*.5))*damage;s.hp-=power;for(let b of s.blocks){let d=Math.hypot((b.x+b.w/2)-x,(b.y+b.h/2)-y);if(d<r&&power>d/r){b.hp-=power*.8;if(b.hp<=0&&b.alive){b.alive=false;debris.push({x:b.x+b.w/2,y:b.y+b.h/2,w:b.w,h:b.h,vx:(b.x-x)*.8,vy:75+Math.random()*65,life:8,color:s.color});let id=`${s.id}-${Math.round(b.x)}-${Math.round(b.y)}`;if(!earned.has(id)){earned.add(id);addCoins(4)}}}}if(s.hp<=0&&s.alive){s.alive=false;addCoins(30);showToast('Stronghold demolished · +30 coins');if(s.barrel)explode(s.x,s.y+s.h*.35,110,5);if(s.money){addCoins(20);showToast('Cash crate recovered · +20 coins')} }}}}
 function detonate(){if(!rocket||rocket.detonated)return;rocket.detonated=true;explode(rocket.x,rocket.y,150,9);rocket.alive=false;finishFlight()}
